const solar = global.get('solar');
const now = Date.now();
let state = flow.get('sim');
if (!state) state = solar.initialState(now);
const issTelemetry = flow.get('issLive') || null;
const command = msg.topic === 'tick' ? { type: 'tick' } : solar.parseCommand(msg.payload);
const next = solar.reduce(state, command, now, { issTelemetry });
flow.set('sim', next.state);
delete msg._session;
msg.payload = next.tick;
const liveIss = solar.isLiveIssActive(next.state.jd, issTelemetry);
node.status({
  fill: next.state.playing ? 'green' : 'grey',
  shape: 'dot',
  text: liveIss ? `${next.label} · ISS direct` : next.label
});
return msg;

const solar = global.get('solar');
msg.payload = solar.catalog();
msg.headers = {
  'Content-Type': 'application/json; charset=utf-8',
  'Cache-Control': 'no-store'
};
msg.statusCode = 200;
return msg;

msg.payload = {
  ok: true,
  editor: global.get('editorEnabled') === true,
  shutdown: global.get('shutdownEnabled') === true
};
msg.headers = {
  'Content-Type': 'application/json; charset=utf-8',
  'Cache-Control': 'no-store'
};
msg.statusCode = 200;
return msg;

const solar = global.get('solar');
const sim = flow.get('sim');
const nowJd = solar.unixToJd(Date.now());
if (sim && Math.abs(sim.jd - nowJd) > 5 / 1440) {
  node.status({ fill: 'grey', shape: 'ring', text: 'En veille (hors présent)' });
  return null;
}
msg.requestTimeout = 3500;
node.status({ fill: 'blue', shape: 'dot', text: 'Lecture ISS…' });
return msg;

const solar = global.get('solar');
if (msg.error || msg.statusCode !== 200 || !msg.payload || typeof msg.payload !== 'object') {
  node.status({ fill: 'grey', shape: 'ring', text: 'Hors ligne — orbite théorique' });
  return null;
}
const latDeg = Number(msg.payload.latitude);
const lonDeg = Number(msg.payload.longitude);
const altitudeKm = Number(msg.payload.altitude);
const velocityKmH = Number(msg.payload.velocity);
const tsSec = Number(msg.payload.timestamp);
if (!Number.isFinite(latDeg) || !Number.isFinite(lonDeg) || !Number.isFinite(altitudeKm)) {
  node.status({ fill: 'yellow', shape: 'ring', text: 'Réponse API incomplète' });
  return null;
}
const sampleMs = Number.isFinite(tsSec) && tsSec > 1e8 ? tsSec * 1000 : Date.now();
const jd = solar.unixToJd(sampleMs);
const velocityKmS = Number.isFinite(velocityKmH) ? velocityKmH / 3600 : 7.66;
const prev = flow.get('issLive');
let dLatPerDay = 0;
let dLonPerDay = 0;
if (prev && Number.isFinite(prev.jd)) {
  const dtDays = jd - prev.jd;
  if (dtDays > 0.5 / 86400 && dtDays < 30 / 86400) {
    dLatPerDay = (latDeg - prev.latDeg) / dtDays;
    let dLon = lonDeg - prev.lonDeg;
    if (dLon > 180) dLon -= 360;
    if (dLon < -180) dLon += 360;
    dLonPerDay = dLon / dtDays;
  }
}
flow.set('issLive', { latDeg, lonDeg, altitudeKm, velocityKmS, jd, dLatPerDay, dLonPerDay });
const latTxt = `${latDeg.toFixed(1).replace('.', ',')}°`;
const lonTxt = `${lonDeg.toFixed(1).replace('.', ',')}°`;
node.status({
  fill: 'green',
  shape: 'dot',
  text: `${latTxt}, ${lonTxt} · ${Math.round(altitudeKm)} km`
});
return null;
